INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.55.0',
  '2026-07-29',
  'Food — план питания',
  E'На странице Food появилась вкладка «📅 План» — меню на несколько дней вперёд.\n— Можно планировать приблизительно: у позиции есть кнопка «≈» — понятно, что будет («что-нибудь мясное», «суп»), но КБЖУ не считается. Сводка так и пишет: «посчитано 6 из 9» — неполная сумма не выдаётся за точную.\n— Можно на нескольких участников: жена, ребёнок (быть пользователями Habits не обязательно). У каждого свой коэффициент порции и цель по калориям; приём пищи бывает общим (входит в план каждого со своим коэффициентом) или личным.\n— День или неделю легко скопировать в другие дни, а готовый день — перенести в дневник одной кнопкой. Записи создаются только в вашем дневнике; если день уже переносили, спросим — заменить или добавить.\n— Поделиться можно двумя способами: через контакт — совместный доступ к тому же плану (право правки выдаётся отдельно), по ссылке-приглашению — получатель забирает себе независимую копию.',
  E'Миграция 0059: food_plans / food_plan_participants / food_plan_slots / food_plan_items / food_plan_shares + расширение CHECK food_meals.source_type на ''plan''.\nАрхитектура: план — «намерение» (позиция хранит kind+ref_id и КЭШ КБЖУ), дневник — «факт» (снимок). Apply делает свежий снимок; КБЖУ своих продуктов подтягиваются актуальными (foodProductSnapshots), чужие ссылки не разрешаются. ref_id намеренно БЕЗ FK — удаление рецепта не ломает план.\nСлоты по day_index (0-based), а не по дате: сдвиг/продление/копирование недели; start_date NULL — шаблонный план. Уменьшение days слоты не удаляет, foodPlanSummary их просто не считает.\nТочность: kind=free | approx+ref | точная позиция. approx-позиции обнуляются в normalizeFoodPlanItem и отдаются счётчиками counted/approx. Свободная позиция может нести ручные КБЖУ (так выглядят копии по ссылке — там ссылки сняты).\nУчастники: общий слот × portion_coef каждому, личный — как есть; итог дня = сумма по участникам (без участников — простая сумма).\nПрава: FoodPlanAccess → (isOwner, canEdit); can_edit правит только состав, участники/шаринг/удаление — владелец (ErrForbidden → 403, новый sentinel в store). apply пишет ТОЛЬКО в дневник вызывающего; mode ''''/add/replace, идемпотентность по source_type=plan+source_id.\nШаринг: deliverShare kind food_plan (доступ) + fpl_<token> redeem (копия, copyFoodPlanTo с keepRefs=false).\nЛимиты: 90 дней, 10 участников, 500 слотов, 50 позиций. Фото в плане нет намеренно — иначе FoodPhotoRefCount пришлось бы расширять.\nЮнит-тесты: сводка по участникам, обнуление approx, apply-слот (масштаб порции, свежий продукт, fallback имени). E2E: сводка 495 ккал на двоих, copy-days, apply + повтор + replace, coef 0.5 (100 г → 50 г), 403 на правку без can_edit, redeem → независимая копия.'
);
